-- Product catalog for the recommendations feature, in its own schema: {catalog}.catalog.
-- Nothing in bronze, silver, gold, agent_api or policy_api is changed (product_copurchase only reads silver).
-- Re-running replaces the four tables.
--
-- 1. Upload the generated files (test_data/out/parquet/) to the raw volume's catalog/ folder:
--      databricks fs cp test_data\out\parquet\products.parquet          dbfs:/Volumes/{catalog}/bronze/raw/catalog/products.parquet --overwrite
--      databricks fs cp test_data\out\parquet\product_variants.parquet  dbfs:/Volumes/{catalog}/bronze/raw/catalog/product_variants.parquet --overwrite
--      databricks fs cp test_data\out\parquet\product_relations.parquet dbfs:/Volumes/{catalog}/bronze/raw/catalog/product_relations.parquet --overwrite
--    and the stylist data (Everly companion plan P4):
--      databricks fs cp test_data\out\parquet\product_launches.parquet dbfs:/Volumes/{catalog}/bronze/raw/catalog/product_launches.parquet --overwrite
--      databricks fs cp test_data\out\parquet\product_styles.parquet   dbfs:/Volumes/{catalog}/bronze/raw/catalog/product_styles.parquet --overwrite
--      databricks fs cp test_data\out\parquet\colour_families.parquet  dbfs:/Volumes/{catalog}/bronze/raw/catalog/colour_families.parquet --overwrite
--      databricks fs cp test_data\out\parquet\colour_harmony.parquet   dbfs:/Volumes/{catalog}/bronze/raw/catalog/colour_harmony.parquet --overwrite
-- 2. python -m test_data.databricks.run_sql --file test_data/databricks/catalog_tables.sql --cli <path-to-databricks.exe>
-- Read by databricks_adapter.READ_QUERIES (get_catalog_variants, get_product_relations, get_product_launches,
-- get_product_styles, get_colour_families, get_colour_harmony); schema in test_data/schema/tables.yaml.

CREATE SCHEMA IF NOT EXISTS {catalog}.catalog
  COMMENT 'Product catalog for recommendations (test data, generated by test_data/generator/catalog.py)'
;
CREATE OR REPLACE TABLE {catalog}.catalog.products AS
SELECT trim(product_id) AS product_id, trim(title) AS title, trim(category) AS category,
       trim(description) AS description, trim(material) AS material, trim(fit) AS fit, trim(season) AS season,
       CAST(list_price AS DOUBLE) AS list_price, trim(currency) AS currency, CAST(active AS BOOLEAN) AS active
FROM read_files('/Volumes/{catalog}/bronze/raw/catalog/products.parquet', format => 'parquet')
;
CREATE OR REPLACE TABLE {catalog}.catalog.product_variants AS
SELECT trim(sku) AS sku, trim(product_id) AS product_id, trim(color) AS color, trim(size) AS size,
       CAST(stock AS INT) AS stock
FROM read_files('/Volumes/{catalog}/bronze/raw/catalog/product_variants.parquet', format => 'parquet')
;
CREATE OR REPLACE TABLE {catalog}.catalog.product_relations AS
SELECT trim(relation_id) AS relation_id, trim(product_id) AS product_id,
       trim(related_product_id) AS related_product_id, trim(relation) AS relation,
       CAST(strength AS DOUBLE) AS strength
FROM read_files('/Volumes/{catalog}/bronze/raw/catalog/product_relations.parquet', format => 'parquet')
;
-- Stylist data (P4): staged launches, style tags, colour families and harmony.
CREATE OR REPLACE TABLE {catalog}.catalog.product_launches AS
SELECT trim(launch_id) AS launch_id, trim(product_id) AS product_id, CAST(planned_at AS TIMESTAMP) AS planned_at,
       trim(headline) AS headline
FROM read_files('/Volumes/{catalog}/bronze/raw/catalog/product_launches.parquet', format => 'parquet')
;
CREATE OR REPLACE TABLE {catalog}.catalog.product_styles AS
SELECT trim(style_id) AS style_id, trim(product_id) AS product_id, trim(style) AS style
FROM read_files('/Volumes/{catalog}/bronze/raw/catalog/product_styles.parquet', format => 'parquet')
;
CREATE OR REPLACE TABLE {catalog}.catalog.colour_families AS
SELECT trim(color) AS color, trim(family) AS family
FROM read_files('/Volumes/{catalog}/bronze/raw/catalog/colour_families.parquet', format => 'parquet')
;
CREATE OR REPLACE TABLE {catalog}.catalog.colour_harmony AS
SELECT trim(harmony_id) AS harmony_id, trim(family) AS family, trim(other_family) AS other_family,
       CAST(strength AS DOUBLE) AS strength
FROM read_files('/Volumes/{catalog}/bronze/raw/catalog/colour_harmony.parquet', format => 'parquet')
;
-- "Bought together": per product pair, orders (not cancelled) containing both, and orders containing the first.
-- Derived from silver.order_items (read only); mirrored by mock_adapter.get_product_copurchase. Re-run after the
-- order data is reloaded.
CREATE OR REPLACE TABLE {catalog}.catalog.product_copurchase AS
WITH op AS (
  SELECT DISTINCT i.order_id, v.product_id
  FROM {catalog}.silver.order_items i
  JOIN {catalog}.silver.orders o ON o.order_id = i.order_id
  JOIN {catalog}.catalog.product_variants v ON v.sku = i.sku
  WHERE o.status <> 'cancelled'
),
n AS (SELECT product_id, count(*) AS orders_with_product FROM op GROUP BY product_id)
SELECT a.product_id, b.product_id AS related_product_id, CAST(count(*) AS INT) AS orders_together,
       CAST(n.orders_with_product AS INT) AS orders_with_product
FROM op a
JOIN op b ON b.order_id = a.order_id AND b.product_id <> a.product_id
JOIN n ON n.product_id = a.product_id
GROUP BY a.product_id, b.product_id, n.orders_with_product
;
-- Row counts, to compare with test_data/out/manifest.json (products 46, product_variants 358, product_relations 84,
-- product_launches 6, product_styles 92, colour_families 25, colour_harmony 21; product_copurchase 90 with the
-- current orders)
SELECT 'products' AS t, count(*) AS n FROM {catalog}.catalog.products
UNION ALL SELECT 'product_variants', count(*) FROM {catalog}.catalog.product_variants
UNION ALL SELECT 'product_relations', count(*) FROM {catalog}.catalog.product_relations
UNION ALL SELECT 'product_launches', count(*) FROM {catalog}.catalog.product_launches
UNION ALL SELECT 'product_styles', count(*) FROM {catalog}.catalog.product_styles
UNION ALL SELECT 'colour_families', count(*) FROM {catalog}.catalog.colour_families
UNION ALL SELECT 'colour_harmony', count(*) FROM {catalog}.catalog.colour_harmony
UNION ALL SELECT 'product_copurchase', count(*) FROM {catalog}.catalog.product_copurchase
